    public static Transport exitFrom(WorldPoint start) {
        if (start == null || start.getPlane() != 1) return null;
        for (Transport exit : deckExits()) if (onDeck(start, exit.getDestination()))
            return new Transport(start, exit.getDestination(), exit.getDisplayInfo(), TransportType.TRANSPORT,
                true, "Cross", "Gangplank", 270, 3);
        return null;
    }
